INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`) VALUES
(40161, 'ruRU', 'Использование подземных сил', 'Уничтожьте проводники племени Хребет Ясновидения на Мурлочьей отмели.', 'Ты видел их, $n?$B$BЭто не обычные мурлоки. Их привлекла лей-линия, что течёт из Азсуны в эти земли.$B$BКаким-то образом они смогли подключиться к её чародейскому потоку и использовать эту силу для своих коварных целей.$B$BЭти нарушения нужно прекратить, если мы хотим сохранить лей-линию целой.'),
(40166, 'ruRU', 'Лей-дела с мурлоками', 'Наполнитесь лей-энергией, находящейся на Мурлочьей отмели.', 'Я видел, как эти мурлоки из племени Хребет Ясновидения призывают младших элементалей — немалый подвиг для мурлока, но их верховный призыватель, Блааргррл, пытается призвать Торретуса из реки.$B$BЯ сомневаюсь, что простой мурлок способен управлять такой мощной сущностью, как Торрентус.$B$BБлааргррл будет глубоко погружён в транс, если решится на такой подвиг. Нам понадобится что-то мощное, чтобы остановить его ритуал.$B$BНаполнись лей-энергией и вернись ко мне.'),
(40243, 'ruRU', 'Разбить оружейные стойки', '', ''),
(40282, 'ruRU', 'Крошечный браконьер, крошечные зверушки', 'Победите Грикиса Крошку в бою питомцев.', ''),
(40337, 'ruRU', 'В замешательстве', '', ''),
(40342, 'ruRU', 'Застать врасплох Сашж''тар', 'Убейте 12 чемпионов Сашж''тар или глубинных ведьм Сашж''тар в бухте Лазурного Шквала.', 'Наги заняты набором морских гигантов для битв королевы Азшары в других землях.$B$BСейчас самое время для удара!'),
(40346, 'ruRU', 'Похищенные припасы', 'Соберите 8 похищенных припасов с обломков кораблей в бухте Лазурного Шквала.', 'Морские гиганты обыскивают обломки кораблей в поисках сокровищ. Всё ценное, что можно найти, будет лучше в руках врайкулов.');
